DO $$ DECLARE u uuid;v uuid;address text;w uuid;p uuid;t uuid;r jsonb;token_ text;n integer;BEGIN SELECT id INTO u FROM public.profiles ORDER BY created_at LIMIT 1;SELECT id,email INTO v,address FROM public.profiles WHERE id<>u ORDER BY created_at LIMIT 1;BEGIN PERFORM set_config('request.jwt.claim.sub',u::text,true);w:=public.create_workspace('Product Development','team');SET LOCAL ROLE authenticated;INSERT INTO public.projects(workspace_id,name,owner_id) VALUES(w,'Reminder verification',u) RETURNING id INTO p;INSERT INTO public.tasks(workspace_id,project_id,title,assignee_id,due_date) VALUES(w,p,'Reminder task',u,current_date+1) RETURNING id INTO t;INSERT INTO public.notification_preferences(user_id,in_app,email,timezone) VALUES(u,'{"deadline":false}','{"deadline":false}','UTC') ON CONFLICT(user_id) DO UPDATE SET in_app=excluded.in_app,email=excluded.email,timezone=excluded.timezone;r:=public.invite_workspace_member(w,address,'viewer','');token_:=r->>'token';RESET ROLE;UPDATE public.workspace_invitations SET expires_at=now()-interval '1 day' WHERE id=(r->>'id')::uuid;PERFORM set_config('request.jwt.claim.sub',v::text,true);SET LOCAL ROLE authenticated;BEGIN PERFORM public.accept_workspace_invitation(token_);RAISE EXCEPTION 'Expired invitation accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM='Expired invitation accepted' THEN RAISE;END IF;END;BEGIN INSERT INTO public.notification_preferences(user_id) VALUES(u);RAISE EXCEPTION 'Other preference write accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;RESET ROLE;PERFORM public.process_deadline_reminders();SELECT count(*) INTO n FROM public.notifications WHERE workspace_id=w AND category='deadline';IF n<>0 THEN RAISE EXCEPTION 'Disabled reminders created';END IF;UPDATE public.notification_preferences SET in_app='{"deadline":true}' WHERE user_id=u;PERFORM public.process_deadline_reminders();PERFORM public.process_deadline_reminders();SELECT count(*) INTO n FROM public.notifications WHERE workspace_id=w AND category='deadline';IF n<>1 THEN RAISE EXCEPTION 'Reminder duplicate prevention failed';END IF;RAISE SQLSTATE 'P0002' USING MESSAGE='reminders_verified';EXCEPTION WHEN no_data_found THEN IF SQLERRM<>'reminders_verified' THEN RAISE;END IF;RAISE NOTICE 'Reminder and expiration checks passed; records rolled back';END;END $$;